Repeatedly divide by 62 and map each remainder to a character, then reverse.
```csharp
const string Alphabet =
  "0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ";
public static string Encode(long n) {
    if (n == 0) return "0";
    var sb = new StringBuilder();
    while (n > 0) { sb.Insert(0, Alphabet[(int)(n % 62)]); n /= 62; }
    return sb.ToString();
}
```
Decoding reverses it: result = result * 62 + index of each character.

```csharp
public enum SpotType { Small, Compact, Large }
public class ParkingSpot {
    public string Id { get; }
    public SpotType Type { get; }
    public Vehicle? Vehicle { get; private set; }
    public bool IsFree => Vehicle is null;
    public void Park(Vehicle v) { if (!IsFree) throw new InvalidOperationException(); Vehicle = v; }
    public void Free() => Vehicle = null;
}
public record Ticket(string Id, Vehicle Vehicle, ParkingSpot Spot, DateTime EntryTime);
```
State changes go through methods, not public setters, so invariants stay inside the entity.

```csharp
public interface IPricingStrategy { decimal Calculate(Ticket t, DateTime exit); }
public class HourlyPricing : IPricingStrategy {
    private readonly Dictionary<VehicleType, decimal> _rates = new() {
        [VehicleType.Bike] = 10, [VehicleType.Car] = 30, [VehicleType.Truck] = 60 };
    public decimal Calculate(Ticket t, DateTime exit) {
        var hours = (int)Math.Ceiling((exit - t.EntryTime).TotalHours);
        return Math.Max(1, hours) * _rates[t.Vehicle.Type];
    }
}
```
Rounding up to the next hour and a minimum charge are common business rules to mention.

```csharp
public class ElevatorCar {
    public int Id { get; }
    public int CurrentFloor { get; private set; }
    public Direction Direction { get; private set; } = Direction.Idle;
    private readonly SortedSet<int> _up = new();
    private readonly SortedSet<int> _down = new(Comparer<int>.Create((a, b) => b.CompareTo(a)));
    public void AddStop(int floor) {
        if (floor > CurrentFloor) _up.Add(floor);
        else if (floor < CurrentFloor) _down.Add(floor);
    }
}
```
A Step() method moves one floor, opens doors at stops and flips direction when a set runs empty.

```csharp
public interface IElevatorState {
    void OnRequest(ElevatorCar car, int floor);
    void OnArrived(ElevatorCar car);
}
public class IdleState : IElevatorState {
    public void OnRequest(ElevatorCar car, int floor) {
        car.AddStop(floor);
        car.SetState(floor > car.CurrentFloor ? new MovingUpState() : new MovingDownState());
    }
    public void OnArrived(ElevatorCar car) { }
}
```
The car forwards events to _state, and each state decides the transition.

```csharp
public interface IVendingState {
    void InsertMoney(VendingMachine m, decimal amount);
    void SelectProduct(VendingMachine m, string code);
    void Cancel(VendingMachine m);
}
```
The VendingMachine context holds the current state, balance and inventory, and forwards each public call to _state. States call m.SetState(...) to move on, for example IdleState.InsertMoney adds to the balance and moves to HasMoneyState.

```csharp
public void SelectProduct(VendingMachine m, string code) {
    if (!m.Inventory.IsAvailable(code)) { m.Display("Sold out"); return; }
    var price = m.Inventory.GetPrice(code);
    if (m.Balance < price) { m.Display($"Insert {price - m.Balance} more"); return; }
    if (!m.CoinBox.CanMakeChange(m.Balance - price)) { m.Refund(); m.SetState(m.Idle); return; }
    m.Inventory.Deduct(code);
    m.ReturnChange(m.Balance - price);
    m.SetState(m.Idle);
}
```
Validation happens before any state change, so a failure never leaves the machine half-updated.

```csharp
public class VendingMachine {
    private IVendingState _state;
    public decimal Balance { get; internal set; }
    public VendingMachine() => _state = new IdleState();
    internal void SetState(IVendingState s) => _state = s;
    public void InsertMoney(decimal amt) => _state.InsertMoney(this, amt);
    public void SelectProduct(string code) => _state.SelectProduct(this, code);
    public void Cancel() => _state.Cancel(this);
}
```
The same shape applies to the elevator: public methods delegate, and states call SetState.

Each node holds its children and an end-of-word marker, and optionally a frequency or top-K list.
```csharp
public class TrieNode {
    public Dictionary<char, TrieNode> Children { get; } = new();
    public bool IsWord { get; set; }
    public int Frequency { get; set; }
}
```
A Dictionary handles any character set; for only lowercase a-z a fixed TrieNode[26] array is faster and smaller per lookup.

```csharp
public void Insert(string word) {
    var node = _root;
    foreach (var c in word) {
        if (!node.Children.TryGetValue(c, out var next))
            node.Children[c] = next = new TrieNode();
        node = next;
    }
    node.IsWord = true;
}
public bool StartsWith(string prefix) => FindNode(prefix) is not null;
```
FindNode walks the same loop but returns null as soon as a character is missing.

