```csharp
public class SeatLockService {
    private readonly object _gate = new();
    public bool TryLock(Show show, IReadOnlyList<ShowSeat> seats, string userId, TimeSpan ttl) {
        lock (_gate) {
            var now = DateTime.UtcNow;
            if (seats.Any(s => !s.IsLockableAt(now))) return false;
            foreach (var s in seats) s.Lock(userId, now + ttl);
            return true;
        }
    }
}
```
Check all seats first, then lock all, inside one critical section; a per-show lock object reduces contention across shows.
